{
  "contract": "BPYC",
  "closure": {
    "site_function": "swapBack",
    "site_call": ".addLiquidityETH",
    "functions": [
      "transfer",
      "transferFrom"
    ],
    "justification": "These functions can be re-entered during the external call in swapBack, affecting the exposed storage variables."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "transfer",
      "transferFrom"
    ],
    "nesting_bound": {
      "transfer": 1,
      "transferFrom": 1
    }
  },
  "phases": {
    "function": "swapBack",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_addLiquidityETH"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_addLiquidityETH",
      "to_marker": "after_addLiquidityETH"
    },
    "post": {
      "name": "post",
      "from_marker": "after_addLiquidityETH",
      "to_marker": "end"
    },
    "linearization_point": "after_addLiquidityETH"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Tracks the amount of _rOwned in-flight during reentrancy",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum__rOwned == _totalProportion + inFlight",
    "stable_formula": "_sum__rOwned == _totalProportion",
    "kind": "additive"
  },
  "composition": {
    "target_property": "_sum__rOwned == _totalProportion",
    "rule": "The exposure invariant ensures that the sum of _rOwned remains consistent with _totalProportion, accounting for in-flight changes during the callback."
  }
}
